node -e "
const fs = require('fs');
const content = fs.readFileSync('/agent/data/project-workspace/workspace.yaml', 'utf8');

// Check all required fields exist
const checks = [
  ['orchestrator block', content.includes('orchestrator:')],
  ['poll_interval_seconds: 30', content.includes('poll_interval_seconds: 30')],
  ['reviewer_max_cycles', content.includes('reviewer_max_cycles: \$REVIEWER_MAX_CYCLES')],
  ['executor_max_retries', content.includes('executor_max_retries: \$EXECUTOR_MAX_RETRIES')],
  ['escalation.channel: slack', content.includes('channel: slack')],
  ['escalation.webhook_url', content.includes('webhook_url: \$SLACK_WEBHOOK_URL')],
];
checks.forEach(([name, pass]) => console.log(pass ? 'PASS' : 'FAIL', name));

// Verify no duplicate top-level keys
const topLevelKeys = [];
const keyRegex = /^([a-z_]+):/gm;
let match;
while ((match = keyRegex.exec(content)) !== null) {
  topLevelKeys.push(match[1]);
}
const unique = [...new Set(topLevelKeys)];
const hasDupes = topLevelKeys.length !== unique.length;
console.log(hasDupes ? 'FAIL' : 'PASS', 'No duplicate top-level keys');
console.log('Top-level keys:', topLevelKeys.filter((k, i, a) => i === a.indexOf(k)).join(', '));
"

